``--phase decode`` measures the two in-place INT2 GEMVs.  ``--phase prefill``
measures the table gather into the staging buffer.  Both use the production
kernels and the same S=224 GPU/host address mixture.  Kernel time is reported
separately from end-to-end ``bench_agentic"    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "build":
        prompts = build_prompts()
        for name, text in prompts.items():
            ids = tokenize(text)
            print(f"  {name:14s} {len(ids):6d} tokens  {len(text):8d} chars")
        return
    if cmd == "save":
        name = sys.argv[2]
        path = D / f"{name}.json"
        path.write_text(json.dumps(collect(), indent=2) + "\n")
        print(f"  saved {path}")
        return
    if cmd == "check":
        name = sys.argv[2]
        reference = json.loads((D / f"{name}.json").read_text())
        report = stats(reference, collect(cached=reference))
        print_report(f"{name} vs current", report)
        return
    if cmd == "compare":
        a, b = sys.argv[2], sys.argv[3]
        ra = json.loads((D / f"{a}.json").read_text())
        rb = json.loads((D / f"{b}.json").read_text())
        print_report(f"{b} vs {a}", stats(ra, rb))
        print_report(f"{a} vs {b}", stats(rb, ra))
        return
    raise SystemExit(f"unknown command {cmd}")


if __name__ == "__main__":
    main()


